Item.method_code:
	string itemTypeId = this.getProperty("item_type_id");
	Innovator innovator = this.getInnovator();
	DataAccessLayer dataAccessLayer = new DataAccessLayer(innovator);
	BusinessLogic businessLogic = new BusinessLogic(dataAccessLayer, innovator);
	return businessLogic.GetWindowSectionControl(itemTypeId);
}

internal class BusinessLogic
{
	private IDataAccessLayer dataAccessLayer;
	private Innovator innovator;

	internal BusinessLogic(IDataAccessLayer dataAccessLayer, Innovator innovator)
	{
		this.dataAccessLayer = dataAccessLayer;
		this.innovator = innovator;
	}

	internal Item GetWindowSectionControl(string itemTypeId)
	{
		Item cuiControls = innovator.newItem("");
		cuiControls.removeAttribute("isNew");
		cuiControls.removeAttribute("isTemp");

		Item itPresentationConfigurationRelship = this.dataAccessLayer.GetITPresentationConfiguration(itemTypeId);
		if (itPresentationConfigurationRelship.isError()) {
			return innovator.newResult(string.Empty);
		}
		Item windowsSectionControls = itPresentationConfigurationRelship.getItemsByXPath("//Item[@type='cui_WindowSectionControl']");

		for (var i = 0; i < windowsSectionControls.getItemCount(); i++) {
			var current = windowsSectionControls.getItemByIndex(i);
			Item controlRules = current.getItemsByXPath("//Item[@type='cui_ControlRule']");

			for (int j = 0; j < controlRules.getItemCount(); j++) {
				var rule = controlRules.getItemByIndex(j).getRelatedItem();
				XmlElement itemTypeIdNode = rule.dom.CreateElement("item_type_id");
				itemTypeIdNode.InnerText = itemTypeId;
				rule.node.AppendChild(itemTypeIdNode);
			}

			cuiControls.appendItem(current);
		}

		if (cuiControls.getItemCount() > 1) {
			cuiControls.removeItem(cuiControls.getItemByIndex(0));
		}

		return cuiControls;
	}
}

internal interface IDataAccessLayer
{
	Item GetITPresentationConfiguration(string itemTypeId);
}

internal class DataAccessLayer : IDataAccessLayer
{
	private Innovator innovator;

	internal DataAccessLayer(Innovator innovator)
	{
		this.innovator = innovator;
	}

	public Item GetITPresentationConfiguration(string itemTypeId)
	{
		Item result = innovator.newItem();

		string aml = string.Format(CultureInfo.InvariantCulture, @"<AML>" +
@"<Item type=""ITPresentationConfiguration"" action=""get"" select=""related_id"">" +
	@"<client>js</client>" +
	@"<related_id>" +
		@"<Item action=""get"" select=""id"">" +
			@"<Relationships>" +
				@"<Item type=""cui_PresentConfigWinSection"" action=""get"" select=""related_id"">" +
					@"<related_id>" +
						@"<Item action=""get"">" +
							@"<location>" +
								@"<Item type=""Location"" action=""get"" select=""name"">" +
									@"<name>SearchGrid</name>" +
								@"</Item>" +
							@"</location>" +
							@"<Relationships>" +
								@"<Item type=""cui_WindowSectionControl"" action=""get"" select=""related_id,action"">" +
									@"<related_id>" +
										@"<Item action=""get"" select=""name,control_type"">" +
											@"<control_type>GridControl</control_type>" +
											@"<name>SearchGrid.Grid</name>" +
											@"<Relationships>" +
												@"<Item type=""cui_ControlRule"" action=""get"" select=""related_id"">" +
													@"<related_id>" +
														@"<Item type=""cui_Rule"" action=""get"" select=""id,name,condition_text,behavior_text"" />" +
													@"</related_id>" +
												@"</Item>" +
											@"</Relationships>" +
										@"</Item>" +
									@"</related_id>" +
								@"</Item>" +
							@"</Relationships>" +
						@"</Item>" +
					@"</related_id>" +
				@"</Item>" +
			@"</Relationships>" +
		@"</Item>" +
	@"</related_id>" +
	@"<source_id>{0}</source_id>" +
@"</Item>" +
@"</AML>", System.Security.SecurityElement.Escape(itemTypeId));

	result.loadAML(aml);

	return result.apply();
}
